            'Only during eco rounds',
            'For post-plant situations',
            'When rushing sites'
          ],
          correct: 2
        },
        {
          question: 'How long does a smoke grenade last?',
          options: [
            '15 seconds',
            '18 seconds',
            '20 seconds',
            '25 seconds'
          ],
          correct: 1
        },
        {
          question: 'What is the best use of a decoy grenade?',
          options: [
            'Fake flash',
            'Fake steps',
            'Fake gunfire',
            'All of the above'
          ],
          correct: 3
        },
        {
          question: 'How can you extend molotov duration?',
          options: [
            'Throw it on elevated surface',
            'Use smoke on it',
            'Cannot be extended',
            'Throw another molotov'
          ],
          correct: 0
        },
        {
          question: 'Which utility can stop a rush most effectively?',
          options: [
            'HE Grenade',
            'Flashbang',
            'Molotov/Incendiary',
            'Smoke'
          ],
          correct: 2
        },
        {
          question: 'What is the best counter to a molotov?',
          options: [
            'HE Grenade',
            'Smoke Grenade',
            'Flash',
            'Wait it out'
          ],
          correct: 1
        },
        {
          question: 'How many flashbangs can you carry?',
          options: [
            'One',
            'Two',
            'Three',
            'Four'
          ],
          correct: 1
        },
        {
          question: 'What determines grenade damage?',
          options: [
            'Distance only',
            'Armor only',
            'Distance and armor',
            'Random'
          ],
          correct: 2
        }
      ]
    }
  ];

  const handleAnswer = (questionIndex, answerIndex) => {
    setUserAnswers({
      ...userAnswers,
      [`${currentTest}_${questionIndex}`]: answerIndex
    });
  };

  const calculateScore = () => {
    let correct = 0;
    let total = tests[currentTest].questions.length;
    
    tests[currentTest].questions.forEach((q, i) => {
      if (userAnswers[`${currentTest}_${i}`] === q.correct) {
        correct++;
      }
    });

    return { correct, total };
  };

  const handleSubmit = async () => {
    const { correct, total } = calculateScore();
    const score = Math.round((correct / total) * 100);
    
    if (auth.currentUser) {
      await saveTestResult(tests[currentTest].id, score);
    }
    
    setShowResults(true);
  };

  return (
    <div className="tests-page">
      <h1>CS2 Knowledge Tests</h1>
      
      <div className="test-navigation">
        {tests.map((test, index) => (
          <button
            key={test.id}
            className={currentTest === index ? 'active' : ''}
            onClick={() => {
              setCurrentTest(index);
              setShowResults(false);
              setUserAnswers({});
            }}
          >
            {test.name}
            {testHistory[test.id] && (
              <span className="best-score">
                Best: {testHistory[test.id].bestScore}%
              </span>
            )}
          </button>
        ))}
      </div>

      <div className="test-content">
        <h2>{tests[currentTest].name} Test</h2>
        
        {!showResults ? (
          <>
            {testHistory[tests[currentTest].id] && (
              <div className="current-best-score">
                Best Score: {testHistory[tests[currentTest].id].bestScore}%
              </div>
            )}
            {tests[currentTest].questions.map((q, questionIndex) => (
              <div key={questionIndex} className="question-card">
                <h3>Question {questionIndex + 1}</h3>
                <p>{q.question}</p>
                <div className="options">
                  {q.options.map((option, optionIndex) => (
                    <button
                      key={optionIndex}
                      className={
                        userAnswers[`${currentTest}_${questionIndex}`] === optionIndex
                          ? 'selected'
                          : ''
                      }
                      onClick={() => handleAnswer(questionIndex, optionIndex)}
                    >
                      {option}
                    </button>
                  ))}
                </div>
              </div>
            ))}
            
            <button 
              className="submit-button"
              onClick={handleSubmit}
            >
              Submit Test
            </button>
          </>
        ) : (
          <div className="results-card">
            <h3>Test Results</h3>
            {(() => {
              const { correct, total } = calculateScore();
              const score = Math.round((correct / total) * 100);
              return (
                <>
                  <p>Your Score: {score}%</p>
                  <p>You got {correct} out of {total} questions correct!</p>
                  {testHistory[tests[currentTest].id] && (
                    <p>Your Best Score: {testHistory[tests[currentTest].id].bestScore}%</p>
                  )}
                  <button
                    className="retry-button"
                    onClick={() => {
                      setShowResults(false);
                      setUserAnswers({});
                    }}
                  >
                    Try Again
                  </button>
                </>
              );
            })()}
          </div>
        )}
      </div>
    </div>
  );
}

export default Tests;
